import { query, v } from "@wizard/sdk";

export default query({
  args: {},
  handler: async (ctx) => {
    const a = await ctx.db.ticket_type.list({ where: { active: true }, limit: 1000 });
    const b = await ctx.db.session.paginate({ where: { stream: a[0]?.id as never } }, { cursor: null, numItems: 200 });
    return a.length + b.items.length;
  },
});
